    "summary": "It s the most demonic structure in WWE, and careers have been permanently altered by its unforgiving steel. Some of the biggest superstars in WWE history, including Shawn Michaels, Mankind, Undertaker, Triple H, Batista, and more, have had signature moments in the Cell. Now, for the first time, fans can watch the greatest Hell in the Cell match in WWE history as they are all featured in their entirety in this collector's set.",
