    "posterCode": "DOC",
    "metadataSource": "TMDB",
    "summary": "Hulk Hogan is an enduring name in sports entertainment. He headlined the first nine WrestleMania events, becoming a global icon still cheered today by generations of Hulkamaniacs. His 2005 induction into the WWE Hall of Fame was inevitable. Now Hulkamaniacs can add to their collection Hulk Hogan’s Unreleased Collector’s Series, a 3 disc DVD packed with 27 matches never before released on DVD that span the career of the Immortal One, from his early days in AWA, through the explosive popularity of Hulkamania in WWE, his shocking departure for WCW, and triumphant return to WWE. This set also includes archival interviews and promos from his legendary career.",
