    "posterCode": "DOC",
    "metadataSource": "TMDB",
    "summary": "Knowing the eyes of the world are upon them, the goal of every WWE Superstar is to appear on a pay-per-view event, and once there, they desire to steal the show by putting on the best match of the night. Now, the WWE Universe can enjoy the best PPV matches of 2013 in one home video collection. Whether they are battling for championship gold, personal pride, to settle a grudge or more, the stars of Raw and SmackDown present more than a dozen of the greatest PPV bouts of the year.",
