    "metadataSource": "TMDB + Pro Wrestling History",
    "summary": "Some of the WILDEST and MOST SPECTACULAR WWF wrestling match-ups take place on Saturday Night's Main Event. Take a look at The Greatest Hits from this hit show. THE MADNESS MEETS THE MANIA: The historic series of events featuring Randy, Elizabeth, Honky Tonk, and even Hulk. TAG TEAM ACTION: Hulk Hogan, Junk Yard Dog and The Haiti Kid vs. The Funk Brothers. THE COLOSSAL CLASH: Big and burly Bam Bam Bigelow takes on Hercules in a battle featuring two of the WWF's biggest men. THE PHOTO FINISH WWF: Heavyweight Champion Hulk Hogan vs. Paul \"Mr. Wonderful\" Orndorff in an INCREDIBLE steel cage match PHOTO FINISH. THE BLOOD FEUD: Rowdy Roddy Piper vs. Paul Orndorff. EAST MEETS WEST: Hulk Hogan vs. Nikolai Volkoff. THE ANIMAL AT PLAY: George Steele enjoys a day at the beach. PLUS MUCH MORE.",
