const basePromotion = ({
  id,
  name,
  logo,
  cardName = null,
  sortName = null,
  homeSection,
  region,
  summary,
  logoUrl = null,
  activeYears = null,
  colors = ["#d8b35d", "#f3f0df"],
  shows = [],
  ppvs = [],
  presentation = "timeline",
}) => ({
  id,
  name,
  cardName: cardName ?? name,
  sortName: sortName ?? cardName ?? name,
  logo,
  logoUrl,
  activeYears: activeYears ?? promotionActiveYears[id] ?? "Archive dates pending",
  homeSection,
  region,
  summary: summary ?? `${name} archive placeholder.`,
  colors,
  shows,
  ppvs,
  presentation,
});

