export function getPromotion(id) {
  return promotions.find((promotion) => promotion.id === id) ?? promotions[0];
}

export function getPromotionYears(promotion) {
  const datedYears = [
    ...promotion.ppvs.map((event) => event.year),
    ...promotion.shows.flatMap((show) => [
      new Date(`${show.startDate}T00:00:00`).getFullYear(),
      new Date(`${show.endDate ?? show.startDate}T00:00:00`).getFullYear(),
    ]),
  ].filter(Boolean);

  if (!datedYears.length) return years;

  const minYear = Math.min(...datedYears);
  const maxYear = Math.max(...datedYears);
  return Array.from({ length: maxYear - minYear + 1 }, (_, index) => minYear + index);
}

export function getYearEvents(promotion, year) {
  const weekly = promotion.shows.flatMap((show) => buildEpisodes(show, year));
  const ppvs = promotion.ppvs.filter((event) => event.year === year);
  return [...weekly, ...ppvs].sort((a, b) => a.date.localeCompare(b.date));
}

export function getShowEpisodes(show, year) {
  return buildEpisodes(show, year);
}

function buildEvents(promotionId, eventsByYear) {
  return Object.entries(eventsByYear).flatMap(([year, events]) =>
    events.map(([date, name, type = "ppv"], index) => ({
      id: `${promotionId}-${type}-${date}`,
      title: name,
      date,
      year: Number(year),
      type,
      eventLabel: type === "ppv" ? "PPV" : "Special",
      posterCode: name
        .split(/\s+/)
        .filter(Boolean)
        .slice(0, 2)
        .map((part) => part[0])
        .join("")
        .toUpperCase(),
      episodeNumber: index + 1,
      metadataSource: "Seeded TMDB-ready",
      posterA: promotionId === "wcw" ? "#263a75" : "#2b2e35",
      posterB: promotionId === "wcw" ? "#d8b35d" : "#d8b35d",
    })),
  );
}

function buildPosterCode(title) {
  return title
    .replace(/^the\s+/i, "")
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
}

function buildAddedDate(id) {
  let hash = 0;
  for (const char of id) hash += char.charCodeAt(0);
  const day = String((hash % 24) + 1).padStart(2, "0");
  return `2026-05-${day}`;
}

function buildEpisodes(show, year) {
  const start = new Date(`${year}-01-01T00:00:00`);
  const end = new Date(`${year}-12-31T00:00:00`);
  const showStart = new Date(`${show.startDate}T00:00:00`);
  const showEnd = new Date(`${show.endDate ?? `${year}-12-31`}T00:00:00`);
  const cursor = new Date(start);
  const results = [];

  while (cursor.getDay() !== show.weekday) {
    cursor.setDate(cursor.getDate() + 1);
  }

  while (cursor <= end) {
    if (cursor >= showStart && cursor <= showEnd) {
      const iso = toIsoDate(cursor);
      const episodeNumber = results.length + 1;
      results.push({
        id: `${show.id}-${iso}`,
        showId: show.id,
        title: `${show.name} ${formatDisplayDate(iso)}`,
        showName: show.name,
        shortName: show.shortName,
        date: iso,
        year,
        type: "weekly",
        episodeNumber,
        season: year,
        posterCode: show.shortName,
        metadataSource: "Generated schedule",
        posterA: show.colorA,
        posterB: show.colorB,
      });
    }

    cursor.setDate(cursor.getDate() + 7);
  }

  return results;
}

export function formatDisplayDate(isoDate) {
  const value = String(isoDate ?? "").trim();
  if (!value) return "Date pending";
  const date = new Date(/^\d{4}-\d{2}-\d{2}$/.test(value) ? `${value}T00:00:00` : value);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat("en", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(date);
}

export function toIsoDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}
